module.exports = [
{ e: "🔍", art: { b: "🔍", s: ["🐜", "🐞", "🕷️", "🐛"], c: ["#4A3A12", "#B09A3A"] },
pt: { h: "O vovô entregou uma lupa para Nina e outra para Leo, e uma caixinha cheia de cartões em branco. “Bem-vindos ao Clube da Lupa!”, anunciou. “Cada dia, vamos conhecer um bichinho e fazer um cartão de colecionador para ele. No fim, vocês vão ter a coleção completa!” Pipoca tentou caçar a primeira formiga do dia.", t: "O que é um inseto?", f: "Os insetos são o maior grupo de animais do planeta: os cientistas já conhecem mais de um milhão de espécies! Todo inseto adulto tem seis patas e o corpo dividido em três partes: cabeça, tórax e abdômen. Na cabeça ficam as antenas, que servem para cheirar e sentir. E muitos insetos têm asas.", x: "Aranhas, escorpiões e centopeias não são insetos! As aranhas têm oito patas e o corpo em duas partes. Mas todos esses bichinhos são parentes: têm uma armadura por fora do corpo, o exoesqueleto, e patas com articulações.", s: ["Os insetos vivem na Terra há mais de 400 milhões de anos, muito antes dos dinossauros.", "Os insetos existem em quase todos os lugares: florestas, desertos, cidades e até na neve.", "Muitos insetos passam por mudanças enormes ao crescer, como a lagarta que vira borboleta."], ex: { t: "Monte um inseto", m: "massinha de 3 cores, palitos de dente ou limpadores de cachimbo, papel", p: ["Faça três bolinhas de massinha e junte em fila: cabeça, tórax e abdômen.", "Espete seis patas no tórax (o meio!) e duas antenas na cabeça. Se quiser, faça asas de papel.", "Agora faça uma aranha: só duas partes e oito patas. Coloque os dois lado a lado e compare."] }, at: "Cartão 1: o inseto", m: "cartões ou papel cartão cortado, lápis de cor, uma caixinha", p: ["Faça o primeiro cartão: desenhe um inseto e escreva o nome das três partes do corpo.", "Escreva atrás: “6 patas, 3 partes, 2 antenas”.", "Decore a caixinha da sua coleção com o nome “Clube da Lupa”."], q: "Qual bichinho você já viu de perto e quer conhecer melhor?" },
en: { h: "Grandpa handed Nina one magnifying glass and Leo another, plus a little box full of blank cards. “Welcome to the Magnifier Club!” he announced. “Every day, we'll meet a little critter and make a collector's card for it. By the end, you'll have the whole collection!” Popcorn tried to catch the first ant of the day.", t: "What is an insect?", f: "Insects are the largest group of animals on the planet: scientists already know more than a million species! Every adult insect has six legs and a body divided into three parts: head, thorax and abdomen. On the head are the antennae, used for smelling and feeling. And many insects have wings.", x: "Spiders, scorpions and centipedes aren't insects! Spiders have eight legs and a body in two parts. But all of these critters are relatives: they have armor on the outside of their bodies, called an exoskeleton, and jointed legs.", s: ["Insects have lived on Earth for more than 400 million years, long before the dinosaurs.", "Insects live almost everywhere: forests, deserts, cities and even in snow.", "Many insects go through huge changes as they grow, like a caterpillar turning into a butterfly."], ex: { t: "Build an insect", m: "play dough in 3 colors, toothpicks or pipe cleaners, paper", p: ["Make three balls of play dough and join them in a row: head, thorax and abdomen.", "Stick six legs into the thorax (the middle!) and two antennae into the head. Add paper wings if you like.", "Now make a spider: only two parts and eight legs. Put them side by side and compare."] }, at: "Card 1: the insect", m: "cards or cut cardstock, colored pencils, a small box", p: ["Make the first card: draw an insect and label the three parts of its body.", "On the back, write: “6 legs, 3 parts, 2 antennae.”", "Decorate your collection box with the name “Magnifier Club.”"], q: "Which little critter have you seen up close and want to get to know better?" },
es: { h: "El abuelo le dio una lupa a Nina y otra a Leo, y una cajita llena de tarjetas en blanco. “¡Bienvenidos al Club de la Lupa!”, anunció. “Cada día vamos a conocer un bichito y hacerle una tarjeta de colección. ¡Al final van a tener la colección completa!” Palomita intentó cazar la primera hormiga del día.", t: "¿Qué es un insecto?", f: "Los insectos son el grupo de animales más grande del planeta: ¡los científicos ya conocen más de un millón de especies! Todo insecto adulto tiene seis patas y el cuerpo dividido en tres partes: cabeza, tórax y abdomen. En la cabeza están las antenas, que sirven para oler y sentir. Y muchos insectos tienen alas.", x: "¡Las arañas, los escorpiones y los ciempiés no son insectos! Las arañas tienen ocho patas y el cuerpo en dos partes. Pero todos estos bichitos son parientes: tienen una armadura por fuera del cuerpo, el exoesqueleto, y patas con articulaciones.", s: ["Los insectos viven en la Tierra hace más de 400 millones de años, mucho antes que los dinosaurios.", "Hay insectos en casi todos lados: bosques, desiertos, ciudades y hasta en la nieve.", "Muchos insectos cambian muchísimo al crecer, como la oruga que se convierte en mariposa."], ex: { t: "Arma un insecto", m: "plastilina de 3 colores, escarbadientes o limpiapipas, papel", p: ["Haz tres bolitas de plastilina y júntalas en fila: cabeza, tórax y abdomen.", "Clava seis patas en el tórax (¡el medio!) y dos antenas en la cabeza. Si quieres, haz alas de papel.", "Ahora haz una araña: solo dos partes y ocho patas. Ponlos uno al lado del otro y compáralos."] }, at: "Tarjeta 1: el insecto", m: "tarjetas o cartulina cortada, lápices de colores, una cajita", p: ["Haz la primera tarjeta: dibuja un insecto y escribe el nombre de las tres partes del cuerpo.", "Atrás escribe: “6 patas, 3 partes, 2 antenas”.", "Decora la cajita de tu colección con el nombre “Club de la Lupa”."], q: "¿Qué bichito viste de cerca y quieres conocer mejor?" } },

{ e: "🐝", art: { b: "🐝", s: ["🍯", "🌼", "🌸", "👑"], c: ["#7A5A0B", "#F0C02C"] },
pt: { h: "No café da manhã, Leo lambuzou o pão de mel e perguntou de onde vinha aquele doce. “De uma fábrica cheia de trabalhadoras”, respondeu o vovô. “Milhares de abelhas, que visitaram milhões de flores para encher esse pote!” Nina olhou o pote com outros olhos.", t: "As abelhas e a colmeia", f: "As abelhas-europeias, as que fazem o mel do mercado, vivem em colmeias com dezenas de milhares de abelhas. Cada colmeia tem uma rainha, que bota os ovos, e milhares de operárias, que são todas fêmeas: elas limpam, cuidam dos filhotes, constroem os favos e buscam néctar e pólen nas flores. Os machos se chamam zangões.", x: "Os favos são feitos de casinhas de seis lados, os hexágonos. Esse formato encaixa sem deixar espaços vazios e usa a menor quantidade de cera para guardar a maior quantidade de mel!", s: ["Uma rainha pode botar mais de mil ovos num só dia.", "As abelhas batem as asas para evaporar a água do néctar, e assim ele vira mel.", "Para fazer um único pote de mel, as abelhas visitam milhões de flores."], ex: { t: "Por que hexágonos?", m: "papel, tesoura, moldes de círculo, quadrado, triângulo e hexágono do mesmo tamanho", p: ["Recorte vários círculos e tente encaixá-los lado a lado, sem buracos: sobram espaços!", "Agora recorte vários hexágonos e encaixe: eles se juntam perfeitamente, como no favo.", "Teste também triângulos e quadrados. Eles encaixam, mas o hexágono é o mais “redondinho”, ótimo para guardar mel e filhotes."] }, at: "Cartão 2: a abelha", m: "cartões, lápis de cor amarelo e preto", p: ["Desenhe uma abelha operária e, ao lado, um pedacinho de favo de mel.", "Escreva as três “profissões” da colmeia: rainha, operária e zangão.", "Guarde o cartão na sua coleção."], q: "Se você morasse numa colmeia, que trabalho gostaria de fazer?" },
en: { h: "At breakfast, Leo smeared honey on his bread and asked where that sweet stuff came from. “From a factory full of workers,” Grandpa answered. “Thousands of bees, who visited millions of flowers to fill that jar!” Nina looked at the jar with new eyes.", t: "Bees and the hive", f: "Honeybees, the ones that make store-bought honey, live in hives with tens of thousands of bees. Each hive has one queen, who lays the eggs, and thousands of workers, who are all female: they clean, care for the young, build the comb and gather nectar and pollen from flowers. The males are called drones.", x: "Honeycomb is made of six-sided cells called hexagons. That shape fits together with no gaps and uses the least amount of wax to store the most honey!", s: ["A queen can lay more than a thousand eggs in a single day.", "Bees fan their wings to evaporate water from the nectar, and that's how it turns into honey.", "To make a single jar of honey, bees visit millions of flowers."], ex: { t: "Why hexagons?", m: "paper, scissors, templates of a circle, square, triangle and hexagon of the same size", p: ["Cut out several circles and try to fit them side by side with no holes: gaps are left over!", "Now cut out several hexagons and fit them together: they join perfectly, like honeycomb.", "Also test triangles and squares. They fit too, but the hexagon is the most “roundish,” great for storing honey and babies."] }, at: "Card 2: the bee", m: "cards, yellow and black colored pencils", p: ["Draw a worker bee and, next to it, a little piece of honeycomb.", "Write the three “jobs” in the hive: queen, worker and drone.", "Put the card in your collection."], q: "If you lived in a hive, what job would you like to do?" },
es: { h: "En el desayuno, Leo untó el pan con miel y preguntó de dónde venía esa cosa dulce. “De una fábrica llena de trabajadoras”, respondió el abuelo. “¡Miles de abejas, que visitaron millones de flores para llenar ese frasco!” Nina miró el frasco con otros ojos.", t: "Las abejas y la colmena", f: "Las abejas melíferas, las que hacen la miel del supermercado, viven en colmenas con decenas de miles de abejas. Cada colmena tiene una reina, que pone los huevos, y miles de obreras, que son todas hembras: limpian, cuidan a las crías, construyen los panales y buscan néctar y polen en las flores. Los machos se llaman zánganos.", x: "¡Los panales están hechos de celditas de seis lados, los hexágonos! Esa forma encaja sin dejar huecos y usa la menor cantidad de cera para guardar la mayor cantidad de miel.", s: ["Una reina puede poner más de mil huevos en un solo día.", "Las abejas baten las alas para evaporar el agua del néctar, y así se convierte en miel.", "Para hacer un solo frasco de miel, las abejas visitan millones de flores."], ex: { t: "¿Por qué hexágonos?", m: "papel, tijera, moldes de círculo, cuadrado, triángulo y hexágono del mismo tamaño", p: ["Recorta varios círculos e intenta encajarlos uno al lado del otro, sin agujeros: ¡quedan huecos!", "Ahora recorta varios hexágonos y encájalos: se juntan perfectamente, como en el panal.", "Prueba también triángulos y cuadrados. Encajan, pero el hexágono es el más “redondito”, ideal para guardar miel y crías."] }, at: "Tarjeta 2: la abeja", m: "tarjetas, lápices amarillo y negro", p: ["Dibuja una abeja obrera y, al lado, un pedacito de panal.", "Escribe los tres “oficios” de la colmena: reina, obrera y zángano.", "Guarda la tarjeta en tu colección."], q: "Si vivieras en una colmena, ¿qué trabajo te gustaría hacer?" } },

{ e: "💃", art: { b: "🐝", s: ["💃", "☀️", "🌸", "🧭"], c: ["#7A5A0B", "#E0A02C"] },
pt: { h: "Nina escondeu um brinquedo no quintal e tentou explicar para Leo onde estava, mas sem falar nada: só com gestos e passinhos. Foi uma bagunça divertida! “As abelhas fazem isso todo dia, e muito melhor”, contou o vovô. “Elas dançam para mostrar às outras onde estão as flores!”", t: "A dança das abelhas", f: "Quando uma abelha encontra flores cheias de néctar, ela volta para a colmeia e faz uma dança especial, chamada dança do requebrado. Ela anda em linha reta balançando o corpo e depois dá a volta, desenhando um oito. A direção da linha reta mostra para que lado as flores estão, em relação ao Sol, e o tempo de requebrado mostra a distância.", x: "Quem descobriu o significado da dança das abelhas foi o cientista austríaco Karl von Frisch, depois de anos observando colmeias. Pela descoberta, ele ganhou o Prêmio Nobel em 1973!", s: ["Quanto mais longa a parte do requebrado, mais longe estão as flores.", "As abelhas também trazem o cheiro das flores no corpo, e as outras sentem com as antenas.", "Dentro da colmeia é escuro, então as outras abelhas “leem” a dança sentindo os movimentos."], ex: { t: "Dança do tesouro", m: "um objeto para esconder, um quintal ou sala, duas ou mais pessoas", p: ["Uma pessoa esconde um “tesouro” e volta para a “colmeia”, um ponto de partida.", "Sem falar, ela dança: anda alguns passos na direção do tesouro balançando o corpo, e balança mais tempo se o tesouro estiver longe.", "Os outros tentam encontrar o tesouro só pela dança. Depois troquem de papel!"] }, at: "Cartão 3: a dança", m: "cartões, lápis de cor", p: ["Desenhe uma abelha fazendo a dança do oito, com setas mostrando o caminho.", "Desenhe o Sol e as flores no canto do cartão.", "Escreva: “A dança mostra a direção e a distância”."], q: "Que outros jeitos de se comunicar sem falar você conhece?" },
en: { h: "Nina hid a toy in the yard and tried to explain to Leo where it was without saying anything: only gestures and little steps. It was a fun mess! “Bees do that every day, and much better,” said Grandpa. “They dance to show each other where the flowers are!”", t: "The bee dance", f: "When a bee finds flowers full of nectar, it goes back to the hive and does a special dance called the waggle dance. It walks in a straight line wiggling its body, then loops back around, tracing a figure eight. The direction of the straight line shows which way the flowers are compared to the Sun, and how long it waggles shows the distance.", x: "The scientist who figured out what the bee dance means was the Austrian Karl von Frisch, after years of watching hives. For that discovery, he won the Nobel Prize in 1973!", s: ["The longer the waggle part, the farther away the flowers are.", "Bees also carry the smell of the flowers on their bodies, and the others sense it with their antennae.", "It's dark inside the hive, so the other bees “read” the dance by feeling the movements."], ex: { t: "Treasure dance", m: "an object to hide, a yard or room, two or more people", p: ["One person hides a “treasure” and comes back to the “hive,” a starting point.", "Without talking, they dance: they take a few steps toward the treasure while wiggling, and wiggle longer if the treasure is far away.", "The others try to find the treasure using only the dance. Then switch roles!"] }, at: "Card 3: the dance", m: "cards, colored pencils", p: ["Draw a bee doing the figure-eight dance, with arrows showing its path.", "Draw the Sun and the flowers in the corner of the card.", "Write: “The dance shows direction and distance.”"], q: "What other ways of communicating without talking do you know?" },
es: { h: "Nina escondió un juguete en el patio e intentó explicarle a Leo dónde estaba, pero sin hablar: solo con gestos y pasitos. ¡Fue un lío divertido! “Las abejas hacen eso todos los días, y mucho mejor”, contó el abuelo. “¡Bailan para mostrarles a las otras dónde están las flores!”", t: "La danza de las abejas", f: "Cuando una abeja encuentra flores llenas de néctar, vuelve a la colmena y hace un baile especial, llamado danza del meneo. Camina en línea recta meneando el cuerpo y después da la vuelta, dibujando un ocho. La dirección de la línea recta muestra hacia qué lado están las flores, en relación con el Sol, y el tiempo del meneo muestra la distancia.", x: "¡Quien descubrió el significado de la danza de las abejas fue el científico austríaco Karl von Frisch, después de años observando colmenas! Por ese descubrimiento ganó el Premio Nobel en 1973.", s: ["Cuanto más larga es la parte del meneo, más lejos están las flores.", "Las abejas también traen el olor de las flores en el cuerpo, y las otras lo sienten con las antenas.", "Dentro de la colmena está oscuro, así que las otras abejas “leen” la danza sintiendo los movimientos."], ex: { t: "Danza del tesoro", m: "un objeto para esconder, un patio o sala, dos o más personas", p: ["Una persona esconde un “tesoro” y vuelve a la “colmena”, un punto de partida.", "Sin hablar, baila: camina unos pasos hacia el tesoro meneando el cuerpo, y menea más tiempo si el tesoro está lejos.", "Los demás intentan encontrar el tesoro solo con la danza. ¡Después cambien de papel!"] }, at: "Tarjeta 3: la danza", m: "tarjetas, lápices de colores", p: ["Dibuja una abeja haciendo la danza del ocho, con flechas que muestren el camino.", "Dibuja el Sol y las flores en una esquina de la tarjeta.", "Escribe: “La danza muestra la dirección y la distancia”."], q: "¿Qué otras formas de comunicarse sin hablar conoces?" } },

{ e: "🌼", art: { b: "🌼", s: ["🐝", "🍓", "🍫", "🌻"], c: ["#5A6A1B", "#E0C03A"] },
pt: { h: "No sítio da vizinha, Nina viu uma caixinha de madeira com abelhas bem pequenas entrando e saindo por um tubinho de cera. “Pode chegar perto, elas não têm ferrão”, disse a vizinha. “São jataís, abelhas brasileiras!” Leo nem acreditou que existiam abelhas que não picam.", t: "Abelhas nativas e a polinização", f: "O Brasil tem centenas de espécies de abelhas nativas sem ferrão, como a jataí, a mandaçaia e a uruçu. Elas fazem um mel delicioso e são ótimas polinizadoras. Polinizar é levar o pólen, um pozinho das flores, de uma flor para outra. Sem isso, muitas plantas não conseguem formar frutos e sementes.", x: "Cerca de três em cada quatro tipos de plantações de comida do mundo ficam melhores com a ajuda de polinizadores, como abelhas, borboletas, morcegos e beija-flores. Até a flor do cacau, que vira chocolate, é polinizada por mosquinhas minúsculas!", s: ["A jataí constrói na entrada do ninho um tubinho de cera que parece uma trombeta.", "As abelhas sem ferrão se defendem mordiscando ou se enroscando no cabelo de quem incomoda.", "Morangos, maçãs, melões e café ficam maiores e mais bonitos quando são bem polinizados."], ex: { t: "Polinizador por um dia", m: "dois papéis coloridos recortados em forma de flor, cotonetes, salgadinho em pó colorido (tipo queijo) ou giz de lousa ralado", p: ["Polvilhe o pozinho no meio de uma das flores de papel: é o pólen.", "Use o cotonete como se fosse uma abelha: “visite” a flor com pólen e depois a outra flor.", "Veja como o pólen viajou de uma flor para a outra! Repare também como o pó fica grudado no “corpo” da abelha."] }, at: "Cartão 4: os polinizadores", m: "cartões, lápis de cor", p: ["Desenhe uma abelha jataí na entrada do ninho com o tubinho de cera.", "Desenhe três comidas que dependem de polinizadores.", "Escreva: “Sem polinizadores, menos frutas!”."], q: "Que fruta você mais ama? Agradeça a um polinizador por ela!" },
en: { h: "At a neighbor's farm, Nina saw a small wooden box with tiny bees going in and out through a little wax tube. “You can come closer, they don't have stingers,” said the neighbor. “They're jataí bees, from Brazil!” Leo couldn't believe there were bees that don't sting.", t: "Native bees and pollination", f: "Across the tropical Americas there are hundreds of species of native stingless bees, like Brazil's jataí. They make delicious honey and are excellent pollinators. Pollinating means carrying pollen, a fine powder from flowers, from one flower to another. Without it, many plants can't make fruit and seeds.", x: "About three out of every four kinds of food crops in the world do better with help from pollinators, like bees, butterflies, bats and hummingbirds. Even the cacao flower, which becomes chocolate, is pollinated by tiny flies!", s: ["The jataí bee builds a little wax tube at the entrance of its nest that looks like a trumpet.", "Stingless bees defend themselves by nibbling or tangling in the hair of anyone who bothers them.", "Strawberries, apples, melons and coffee grow bigger and better when they're well pollinated."], ex: { t: "Pollinator for a day", m: "two colored paper flowers, cotton swabs, cheese-puff dust or grated chalk", p: ["Sprinkle the powder in the middle of one paper flower: it's the pollen.", "Use the cotton swab like a bee: “visit” the flower with pollen and then the other flower.", "See how the pollen traveled from one flower to the other! Notice how the powder sticks to the bee's “body” too."] }, at: "Card 4: pollinators", m: "cards, colored pencils", p: ["Draw a jataí bee at its nest entrance with the little wax tube.", "Draw three foods that depend on pollinators.", "Write: “No pollinators, less fruit!”"], q: "What fruit do you love most? Thank a pollinator for it!" },
es: { h: "En el campo de una vecina, Nina vio una cajita de madera con abejas bien chiquitas entrando y saliendo por un tubito de cera. “Puedes acercarte, no tienen aguijón”, dijo la vecina. “¡Son yateís, abejas nativas!” Leo no podía creer que existieran abejas que no pican.", t: "Abejas nativas y la polinización", f: "En las zonas cálidas de América Latina hay cientos de especies de abejas nativas sin aguijón, como la yateí. Hacen una miel riquísima y son excelentes polinizadoras. Polinizar es llevar el polen, un polvito de las flores, de una flor a otra. Sin eso, muchas plantas no pueden formar frutos y semillas.", x: "¡Cerca de tres de cada cuatro tipos de cultivos de comida del mundo salen mejor con ayuda de polinizadores, como abejas, mariposas, murciélagos y colibríes! Hasta la flor del cacao, que se convierte en chocolate, la polinizan mosquitas diminutas.", s: ["La yateí construye en la entrada del nido un tubito de cera que parece una trompeta.", "Las abejas sin aguijón se defienden mordisqueando o enredándose en el pelo de quien las molesta.", "Las frutillas, las manzanas, los melones y el café salen más grandes y lindos cuando están bien polinizados."], ex: { t: "Polinizador por un día", m: "dos flores de papel de colores, hisopos, polvo de chizitos o tiza rallada", p: ["Espolvorea el polvito en el medio de una de las flores de papel: es el polen.", "Usa el hisopo como si fuera una abeja: “visita” la flor con polen y después la otra flor.", "¡Mira cómo viajó el polen de una flor a la otra! Fíjate también cómo el polvo se pega al “cuerpo” de la abeja."] }, at: "Tarjeta 4: los polinizadores", m: "tarjetas, lápices de colores", p: ["Dibuja una abeja yateí en la entrada del nido con el tubito de cera.", "Dibuja tres comidas que dependen de los polinizadores.", "Escribe: “¡Sin polinizadores, menos frutas!”."], q: "¿Qué fruta te gusta más? ¡Agradécele a un polinizador por ella!" } },

{ e: "🐜", art: { b: "🐜", s: ["🍬", "🏋️", "🕳️", "👑"], c: ["#5A2A0B", "#B05A2C"] },
pt: { h: "Leo deixou cair um pedacinho de biscoito na calçada e, em poucos minutos, apareceu uma fila de formigas levando os farelos embora. “Como elas souberam tão rápido?”, perguntou. “Uma formiga achou e deixou uma trilha de cheiro até o formigueiro”, explicou o vovô. “As outras só seguiram o caminho!”", t: "As formigas", f: "As formigas vivem em colônias, que podem ter de algumas dezenas a milhões de formigas, com uma ou mais rainhas. Elas se comunicam principalmente pelo cheiro: deixam trilhas químicas no chão e se cumprimentam tocando as antenas. Cada formiga tem um trabalho: cuidar dos ovos, limpar, defender ou buscar comida.", x: "Os cientistas estimaram que existem uns 20 quatrilhões de formigas na Terra, ou seja, mais de 2 milhões de formigas para cada pessoa do planeta! E muitas conseguem carregar dezenas de vezes o próprio peso.", s: ["As formigas existem há mais de 100 milhões de anos, desde a época dos dinossauros.", "Quando uma trilha de cheiro para de levar a comida, o cheiro some, e as formigas procuram outro caminho.", "Algumas formigas fazem pontes e jangadas com o próprio corpo para atravessar buracos e água."], ex: { t: "Observando a trilha", m: "uma colher de açúcar ou um pedacinho de fruta, um papel, uma lupa, um quintal ou calçada", p: ["Com um adulto, coloque o açúcar sobre um papel perto de onde você já viu formigas, ao ar livre.", "Espere e observe com a lupa: quanto tempo a primeira demora? Elas formam uma fila?", "Passe o dedo atravessando a trilha, apagando o cheiro. O que as formigas fazem? Depois de observar, deixe-as em paz."] }, at: "Cartão 5: a formiga", m: "cartões, lápis de cor", p: ["Desenhe um formigueiro por dentro, com túneis, salas de ovos e a rainha.", "Desenhe uma fila de formigas carregando comida.", "Escreva: “Mais de 2 milhões de formigas para cada pessoa!”."], q: "Se você fosse uma formiga, qual trabalho escolheria no formigueiro?" },
en: { h: "Leo dropped a little piece of cookie on the sidewalk and, within minutes, a line of ants showed up carrying the crumbs away. “How did they find out so fast?” he asked. “One ant found it and left a scent trail back to the nest,” Grandpa explained. “The others just followed the path!”", t: "Ants", f: "Ants live in colonies, which can have anywhere from a few dozen to millions of ants, with one or more queens. They communicate mainly by smell: they leave chemical trails on the ground and greet each other by touching antennae. Every ant has a job: caring for eggs, cleaning, defending or finding food.", x: "Scientists have estimated there are about 20 quadrillion ants on Earth, which means more than 2 million ants for every person on the planet! And many can carry dozens of times their own weight.", s: ["Ants have existed for more than 100 million years, since the time of the dinosaurs.", "When a scent trail stops leading to food, the scent fades, and the ants look for another way.", "Some ants make bridges and rafts out of their own bodies to cross gaps and water."], ex: { t: "Watching the trail", m: "a spoonful of sugar or a bit of fruit, a sheet of paper, a magnifying glass, a yard or sidewalk", p: ["With a grown-up, put the sugar on a piece of paper near where you've seen ants, outdoors.", "Wait and watch with the magnifying glass: how long does the first one take? Do they form a line?", "Run your finger across the trail, wiping away the scent. What do the ants do? After watching, leave them in peace."] }, at: "Card 5: the ant", m: "cards, colored pencils", p: ["Draw the inside of an ant nest, with tunnels, egg rooms and the queen.", "Draw a line of ants carrying food.", "Write: “More than 2 million ants for every person!”"], q: "If you were an ant, which job would you choose in the nest?" },
es: { h: "A Leo se le cayó un pedacito de galletita en la vereda y, en pocos minutos, apareció una fila de hormigas llevándose las migas. “¿Cómo se enteraron tan rápido?”, preguntó. “Una hormiga lo encontró y dejó un rastro de olor hasta el hormiguero”, explicó el abuelo. “¡Las otras solo siguieron el camino!”", t: "Las hormigas", f: "Las hormigas viven en colonias, que pueden tener desde algunas decenas hasta millones de hormigas, con una o más reinas. Se comunican sobre todo por el olor: dejan rastros químicos en el suelo y se saludan tocándose las antenas. Cada hormiga tiene un trabajo: cuidar los huevos, limpiar, defender o buscar comida.", x: "¡Los científicos calcularon que hay unos 20 mil billones de hormigas en la Tierra, o sea, más de 2 millones de hormigas por cada persona del planeta! Y muchas pueden cargar decenas de veces su propio peso.", s: ["Las hormigas existen desde hace más de 100 millones de años, desde la época de los dinosaurios.", "Cuando un rastro de olor deja de llevar a la comida, el olor desaparece y las hormigas buscan otro camino.", "Algunas hormigas hacen puentes y balsas con su propio cuerpo para cruzar huecos y agua."], ex: { t: "Observando el rastro", m: "una cucharada de azúcar o un pedacito de fruta, un papel, una lupa, un patio o vereda", p: ["Con un adulto, pon el azúcar sobre un papel cerca de donde viste hormigas, al aire libre.", "Espera y observa con la lupa: ¿cuánto tarda la primera? ¿Forman una fila?", "Pasa el dedo atravesando el rastro, borrando el olor. ¿Qué hacen las hormigas? Después de observar, déjalas tranquilas."] }, at: "Tarjeta 5: la hormiga", m: "tarjetas, lápices de colores", p: ["Dibuja un hormiguero por dentro, con túneles, salas de huevos y la reina.", "Dibuja una fila de hormigas cargando comida.", "Escribe: “¡Más de 2 millones de hormigas por cada persona!”."], q: "Si fueras una hormiga, ¿qué trabajo elegirías en el hormiguero?" } },

{ e: "🍃", art: { b: "🐜", s: ["🍃", "🍄", "🌳", "🏡"], c: ["#2A4A1B", "#6A9A3A"] },
pt: { h: "No jardim, a roseira da vovó amanheceu cheia de buraquinhos redondos nas folhas. Seguindo os pedacinhos verdes que andavam sozinhos pelo chão, Nina e Leo encontraram uma fila de formigas carregando folhas como guarda-chuvas. “São saúvas!”, disse o vovô. “E sabem o que elas fazem com essas folhas? Elas não comem!”", t: "As formigas agricultoras", f: "As saúvas, ou formigas-cortadeiras, cortam pedacinhos de folhas e levam para o ninho, mas não comem as folhas. Lá dentro, elas mastigam as folhas e as usam como adubo para cultivar um fungo, parecido com um mofo, que é a comida delas. As formigas eram agricultoras milhões de anos antes dos seres humanos!", x: "Um ninho de saúvas pode ter milhões de formigas, centenas de câmaras e chegar a vários metros de profundidade debaixo da terra! Lá dentro tem até “salas de lixo” e túneis de ventilação.", s: ["Cada saúva tem um tamanho e um trabalho: as maiores cortam e defendem, e as menores cuidam do fungo.", "Algumas formiguinhas pequenas viajam em cima das folhas, protegendo as carregadoras de moscas.", "Em algumas regiões do Brasil, a rainha da saúva, chamada içá, é comida torrada há muito tempo."], ex: { t: "Corrida das cortadeiras", m: "folhas secas ou de papel, uma tesoura sem ponta, dois potes (o ninho), um cronômetro", p: ["Recorte várias folhas em pedacinhos do tamanho de uma moeda.", "Em 1 minuto, leve os pedacinhos, um de cada vez, de um pote até o outro, do outro lado da sala.", "Quantos você levou? Agora tente com uma “equipe”: cada um leva um pedaço até a metade e passa para o próximo. Assim é mais rápido?"] }, at: "Cartão 6: a saúva", m: "cartões, lápis de cor", p: ["Desenhe uma saúva carregando um pedaço de folha, com uma formiguinha em cima.", "Desenhe a horta de fungos dentro do ninho.", "Escreva: “Agricultoras há milhões de anos!”."], q: "Se você tivesse uma horta, o que plantaria?" },
en: { h: "In the garden, Grandma's rosebush woke up covered in little round holes in its leaves. Following the bits of green that seemed to walk on their own across the ground, Nina and Leo found a line of ants carrying leaves like umbrellas. “Leafcutter ants!” said Grandpa. “And do you know what they do with those leaves? They don't eat them!”", t: "Farmer ants", f: "Leafcutter ants cut little pieces of leaves and take them back to the nest, but they don't eat the leaves. Inside, they chew them up and use them as fertilizer to grow a fungus, something like mold, which is their food. Ants were farmers millions of years before humans!", x: "A leafcutter nest can have millions of ants and hundreds of chambers, reaching several meters deep underground! Inside there are even “trash rooms” and ventilation tunnels.", s: ["Each leafcutter has a size and a job: the biggest cut and defend, and the smallest care for the fungus.", "Some tiny ants ride on top of the leaves, protecting the carriers from flies.", "In some regions of Brazil, the leafcutter queen, called içá, has long been eaten roasted."], ex: { t: "Leafcutter race", m: "dry leaves or paper leaves, safety scissors, two containers (the nest), a timer", p: ["Cut several leaves into pieces about the size of a coin.", "In 1 minute, carry the pieces one at a time from one container to the other, across the room.", "How many did you carry? Now try it as a “team”: each person carries a piece halfway and hands it to the next. Is that faster?"] }, at: "Card 6: the leafcutter", m: "cards, colored pencils", p: ["Draw a leafcutter carrying a piece of leaf, with a tiny ant riding on top.", "Draw the fungus garden inside the nest.", "Write: “Farmers for millions of years!”"], q: "If you had a garden, what would you plant?" },
es: { h: "En el jardín, el rosal de la abuela amaneció lleno de agujeritos redondos en las hojas. Siguiendo los pedacitos verdes que caminaban solos por el suelo, Nina y Leo encontraron una fila de hormigas cargando hojas como paraguas. “¡Son hormigas cortadoras!”, dijo el abuelo. “¿Y saben qué hacen con esas hojas? ¡No se las comen!”", t: "Las hormigas agricultoras", f: "Las hormigas cortadoras cortan pedacitos de hojas y los llevan al nido, pero no se comen las hojas. Adentro, las mastican y las usan como abono para cultivar un hongo, parecido al moho, que es su comida. ¡Las hormigas fueron agricultoras millones de años antes que los seres humanos!", x: "¡Un nido de hormigas cortadoras puede tener millones de hormigas, cientos de cámaras y llegar a varios metros de profundidad bajo la tierra! Adentro hay hasta “salas de basura” y túneles de ventilación.", s: ["Cada hormiga cortadora tiene un tamaño y un trabajo: las más grandes cortan y defienden, y las más chicas cuidan el hongo.", "Algunas hormiguitas chiquitas viajan arriba de las hojas, protegiendo a las cargadoras de las moscas.", "En algunos lugares de América Latina, las reinas de las hormigas cortadoras se comen tostadas desde hace mucho tiempo."], ex: { t: "Carrera de las cortadoras", m: "hojas secas o de papel, tijera sin punta, dos recipientes (el nido), un cronómetro", p: ["Corta varias hojas en pedacitos del tamaño de una moneda.", "En 1 minuto, lleva los pedacitos, de a uno, de un recipiente al otro, al otro lado de la sala.", "¿Cuántos llevaste? Ahora prueba en “equipo”: cada uno lleva un pedazo hasta la mitad y se lo pasa al siguiente. ¿Así es más rápido?"] }, at: "Tarjeta 6: la cortadora", m: "tarjetas, lápices de colores", p: ["Dibuja una hormiga cortadora llevando un pedazo de hoja, con una hormiguita arriba.", "Dibuja la huerta de hongos dentro del nido.", "Escribe: “¡Agricultoras hace millones de años!”."], q: "Si tuvieras una huerta, ¿qué plantarías?" } },

{ e: "🏰", art: { b: "🏰", s: ["🐜", "🌬️", "🌾", "🛰️"], c: ["#7A4A1B", "#C28A4A"] },
pt: { h: "Na estrada, Leo viu no pasto um montão de terra quase da altura dele. “É uma casinha de quê?”, perguntou. “De cupins!”, respondeu o vovô. “E ela tem até ar-condicionado natural. Os engenheiros estudam os cupinzeiros para fazer prédios mais fresquinhos!”", t: "Os cupins construtores", f: "Os cupins são insetos que vivem em colônias enormes, com rei e rainha. Muitos constroem cupinzeiros com terra, saliva e cocô, que endurecem como tijolo. Lá dentro há uma rede de túneis por onde o ar quente sobe e sai, e o ar fresco entra, mantendo a temperatura agradável. Na natureza, os cupins ajudam a reciclar madeira e folhas mortas.", x: "No Nordeste do Brasil existe uma região com uns 200 milhões de montes de terra feitos por cupins, ocupando uma área do tamanho de um país inteiro, como a Grã-Bretanha! Alguns têm cerca de 4 mil anos e dá para ver a região até por imagens de satélite.", s: ["A rainha de alguns cupins pode viver muitos anos e botar milhares de ovos por dia.", "No Cerrado, alguns cupinzeiros brilham à noite, por causa de larvas de vaga-lume que moram neles.", "Os cupins são parentes próximos das baratas."], ex: { t: "Ar quente sobe", m: "papel, tesoura, linha, um adulto, uma fonte de calor segura (uma xícara de água bem quente ou o ar de um aquecedor)", p: ["Desenhe uma espiral num círculo de papel, recorte pela linha e prenda uma linha no centro.", "Com um adulto, segure a espiral pendurada acima da xícara de água bem quente, sem encostar.", "A espiral começa a girar! O ar quente sobe, como nas chaminés dos cupinzeiros, que deixam o calor sair por cima."] }, at: "Cartão 7: o cupim", m: "cartões, lápis de cor marrom", p: ["Desenhe um cupinzeiro cortado ao meio, com os túneis e setas mostrando o ar quente subindo.", "Desenhe o rei e a rainha no centro.", "Escreva: “Ar-condicionado natural!”."], q: "Que ideia da natureza você usaria para construir uma casa?" },
en: { h: "On the road, Leo saw a huge mound of dirt in a pasture, almost as tall as he was. “What lives in that?” he asked. “Termites!” Grandpa answered. “And it even has natural air conditioning. Engineers study termite mounds to make cooler buildings!”", t: "Termite builders", f: "Termites are insects that live in huge colonies with a king and a queen. Many build mounds out of soil, saliva and poop, which harden like brick. Inside there's a network of tunnels where hot air rises and escapes, and fresh air comes in, keeping the temperature pleasant. In nature, termites help recycle dead wood and leaves.", x: "In northeastern Brazil there's a region with about 200 million mounds of soil made by termites, covering an area the size of a whole country, like Great Britain! Some are about 4,000 years old, and the region can even be seen in satellite images.", s: ["The queen of some termite species can live many years and lay thousands of eggs a day.", "In Brazil's Cerrado, some termite mounds glow at night, because of firefly larvae living in them.", "Termites are close relatives of cockroaches."], ex: { t: "Hot air rises", m: "paper, scissors, thread, a grown-up, a safe heat source (a mug of very hot water or air from a heater)", p: ["Draw a spiral on a paper circle, cut along the line and attach a thread to the center.", "With a grown-up, hold the spiral hanging above the mug of very hot water, without touching it.", "The spiral starts to spin! Hot air rises, like in the chimneys of termite mounds, which let heat escape out the top."] }, at: "Card 7: the termite", m: "cards, brown colored pencils", p: ["Draw a termite mound cut in half, with its tunnels and arrows showing hot air rising.", "Draw the king and queen in the center.", "Write: “Natural air conditioning!”"], q: "What idea from nature would you use to build a house?" },
es: { h: "En la ruta, Leo vio en el campo un montón de tierra casi de su altura. “¿Una casita de qué?”, preguntó. “¡De termitas!”, respondió el abuelo. “Y tiene hasta aire acondicionado natural. ¡Los ingenieros estudian los termiteros para hacer edificios más fresquitos!”", t: "Las termitas constructoras", f: "Las termitas son insectos que viven en colonias enormes, con rey y reina. Muchas construyen termiteros con tierra, saliva y caca, que se endurecen como ladrillo. Adentro hay una red de túneles por donde el aire caliente sube y sale, y entra aire fresco, manteniendo una temperatura agradable. En la naturaleza, las termitas ayudan a reciclar madera y hojas muertas.", x: "¡En el nordeste de Brasil hay una región con unos 200 millones de montículos de tierra hechos por termitas, que ocupa un área del tamaño de un país entero, como Gran Bretaña! Algunos tienen unos 4.000 años y la región se puede ver hasta en imágenes satelitales.", s: ["La reina de algunas termitas puede vivir muchos años y poner miles de huevos por día.", "En el Cerrado brasileño, algunos termiteros brillan de noche, por las larvas de luciérnaga que viven en ellos.", "Las termitas son parientes cercanas de las cucarachas."], ex: { t: "El aire caliente sube", m: "papel, tijera, hilo, un adulto, una fuente de calor segura (una taza de agua bien caliente o el aire de una estufa)", p: ["Dibuja una espiral en un círculo de papel, recórtala por la línea y ata un hilo en el centro.", "Con un adulto, sostén la espiral colgada encima de la taza de agua bien caliente, sin tocarla.", "¡La espiral empieza a girar! El aire caliente sube, como en las chimeneas de los termiteros, que dejan salir el calor por arriba."] }, at: "Tarjeta 7: la termita", m: "tarjetas, lápices marrones", p: ["Dibuja un termitero cortado por la mitad, con los túneles y flechas que muestren el aire caliente subiendo.", "Dibuja al rey y a la reina en el centro.", "Escribe: “¡Aire acondicionado natural!”."], q: "¿Qué idea de la naturaleza usarías para construir una casa?" } },

{ e: "🐞", art: { b: "🐞", s: ["🌿", "🔴", "⚫", "🌹"], c: ["#7A1B0B", "#E03A2C"] },
pt: { h: "Uma joaninha pousou no braço de Nina e foi subindo devagarinho até a ponta do dedo. Depois abriu as asas e voou. “Ela veio dar bom-dia!”, disse Nina. “E veio trabalhar também”, riu o vovô. “As joaninhas são as melhores amigas das hortas: elas comem os pulgões que estragam as plantas.”", t: "As joaninhas", f: "As joaninhas são besouros pequenos e coloridos. Muitas espécies comem pulgões, bichinhos minúsculos que sugam a seiva das plantas e as deixam fracas. Por isso, os agricultores adoram joaninhas! As cores fortes, como o vermelho com bolinhas pretas, avisam aos passarinhos: “eu tenho um gosto ruim, não me coma!”.", x: "Uma única joaninha pode comer dezenas de pulgões num só dia, e milhares durante a vida! Quando se assusta, ela solta um líquido amarelo e fedido pelas articulações das patas, para afastar predadores.", s: ["Existem milhares de espécies de joaninhas, de várias cores: vermelhas, amarelas, laranja e até pretas com pintas vermelhas.", "As asas que a joaninha usa para voar ficam dobradinhas debaixo da carapaça colorida.", "O número de pintas não mostra a idade da joaninha: ele depende da espécie."], ex: { t: "Cores de aviso", m: "papel verde (o fundo), papéis recortados em joaninhas de várias cores: vermelho, verde, marrom e amarelo", p: ["Espalhe as joaninhas de papel sobre o fundo verde.", "Peça para alguém olhar rapidinho, por 3 segundos, e dizer quais viu primeiro.", "As vermelhas e amarelas chamam mais atenção! As joaninhas não querem se esconder: querem ser vistas para avisar que não são gostosas."] }, at: "Cartão 8: a joaninha", m: "cartões, lápis de cor", p: ["Desenhe uma joaninha numa folha comendo pulgões.", "Invente uma joaninha de cor diferente e conte as pintas dela.", "Escreva: “Amiga das hortas!”."], q: "Que outros animais você conhece que usam cores para dar um aviso?" },
en: { h: "A ladybug landed on Nina's arm and slowly climbed up to the tip of her finger. Then it opened its wings and flew away. “It came to say good morning!” said Nina. “And it came to work too,” Grandpa laughed. “Ladybugs are a garden's best friends: they eat the aphids that harm plants.”", t: "Ladybugs", f: "Ladybugs are small, colorful beetles. Many species eat aphids, tiny bugs that suck plant sap and make plants weak. That's why farmers love ladybugs! Their bright colors, like red with black spots, warn birds: “I taste bad, don't eat me!”", x: "A single ladybug can eat dozens of aphids in one day, and thousands in its lifetime! When it's scared, it oozes a smelly yellow liquid from its leg joints to keep predators away.", s: ["There are thousands of ladybug species in many colors: red, yellow, orange and even black with red spots.", "The wings a ladybug flies with stay folded up under its colorful shell.", "The number of spots doesn't show a ladybug's age: it depends on the species."], ex: { t: "Warning colors", m: "green paper (the background), paper ladybugs in several colors: red, green, brown and yellow", p: ["Spread the paper ladybugs on the green background.", "Ask someone to take a quick look, for 3 seconds, and say which ones they saw first.", "The red and yellow ones stand out most! Ladybugs don't want to hide: they want to be seen so they can warn that they don't taste good."] }, at: "Card 8: the ladybug", m: "cards, colored pencils", p: ["Draw a ladybug on a leaf eating aphids.", "Invent a ladybug of a different color and count its spots.", "Write: “A garden's friend!”"], q: "What other animals do you know that use colors as a warning?" },
es: { h: "Una vaquita de San Antonio se posó en el brazo de Nina y fue subiendo despacito hasta la punta del dedo. Después abrió las alas y voló. “¡Vino a darme los buenos días!”, dijo Nina. “Y también vino a trabajar”, se rió el abuelo. “Las vaquitas son las mejores amigas de las huertas: se comen los pulgones que arruinan las plantas.”", t: "Las vaquitas de San Antonio", f: "Las vaquitas de San Antonio, o mariquitas, son escarabajos chiquitos y coloridos. Muchas especies comen pulgones, bichitos diminutos que chupan la savia de las plantas y las debilitan. ¡Por eso a los agricultores les encantan! Los colores fuertes, como el rojo con lunares negros, les avisan a los pájaros: “tengo feo sabor, ¡no me comas!”.", x: "¡Una sola vaquita puede comer decenas de pulgones en un día, y miles durante su vida! Cuando se asusta, suelta un líquido amarillo y apestoso por las articulaciones de las patas, para alejar a los depredadores.", s: ["Hay miles de especies de vaquitas, de muchos colores: rojas, amarillas, naranjas y hasta negras con lunares rojos.", "Las alas que usa para volar están dobladitas debajo del caparazón de colores.", "La cantidad de lunares no muestra la edad de la vaquita: depende de la especie."], ex: { t: "Colores de aviso", m: "papel verde (el fondo), vaquitas de papel de varios colores: rojo, verde, marrón y amarillo", p: ["Desparrama las vaquitas de papel sobre el fondo verde.", "Pídele a alguien que mire rapidito, 3 segundos, y diga cuáles vio primero.", "¡Las rojas y amarillas llaman más la atención! Las vaquitas no quieren esconderse: quieren que las vean para avisar que no son sabrosas."] }, at: "Tarjeta 8: la vaquita", m: "tarjetas, lápices de colores", p: ["Dibuja una vaquita en una hoja comiendo pulgones.", "Inventa una vaquita de otro color y cuenta sus lunares.", "Escribe: “¡Amiga de las huertas!”."], q: "¿Qué otros animales conoces que usan colores para avisar algo?" } },

{ e: "✨", art: { b: "✨", s: ["🌙", "💡", "🌳", "💚"], c: ["#0B1B2A", "#C2E04A"] },
pt: { h: "No sítio, quando escureceu, o gramado começou a piscar com luzinhas verdes, como estrelas pequenininhas voando. “Vaga-lumes!”, cochichou Nina, encantada. Leo quis saber se as luzes esquentavam, como uma lâmpada. “Essa é a parte mais incrível”, disse o vovô. “É uma luz fria!”", t: "Os vaga-lumes", f: "Os vaga-lumes são besouros que fazem luz com o próprio corpo. Na barriga, eles misturam substâncias químicas que, juntas, brilham. Esse brilho se chama bioluminescência. Cada espécie pisca num ritmo diferente, como um código secreto, para os machos e as fêmeas se encontrarem.", x: "A luz do vaga-lume quase não esquenta: praticamente toda a energia vira luz! Uma lâmpada antiga, daquelas com fiozinho, desperdiçava a maior parte da energia em calor.", s: ["O Brasil tem centenas de espécies de vaga-lumes.", "Os filhotes de vaga-lume, as larvas, também brilham e comem lesmas e caracóis.", "As luzes fortes das cidades atrapalham os vaga-lumes a se encontrarem no escuro."], ex: { t: "Luz que muda com a temperatura", m: "duas pulseiras de neon (bastões de luz) iguais, um copo com água quente da torneira e um com água gelada, um adulto", p: ["Com um adulto, ative as duas pulseiras de neon dobrando até ouvir o “crec”.", "Coloque uma no copo de água quente e a outra no copo de água gelada.", "Depois de um minuto, apague a luz e compare: a da água quente brilha mais forte! A luz vem de uma reação química, como no vaga-lume, e o calor deixa a reação mais rápida."] }, at: "Cartão 9: o vaga-lume", m: "cartões, papel preto, lápis de cor ou giz amarelo e verde", p: ["Num cartão preto, desenhe vaga-lumes piscando no meio do mato.", "Invente o código de piscadas do seu vaga-lume, como pisca-pisca-pausa.", "Escreva: “Luz fria, feita pelo corpo!”."], q: "O que podemos fazer para que os vaga-lumes continuem brilhando perto das cidades?" },
en: { h: "Out in the countryside, when it got dark, the lawn began blinking with little green lights, like tiny stars flying around. “Fireflies!” Nina whispered, delighted. Leo wanted to know if the lights got hot, like a light bulb. “That's the most amazing part,” said Grandpa. “It's cold light!”", t: "Fireflies", f: "Fireflies are beetles that make light with their own bodies. In their bellies, they mix chemicals that glow when they come together. That glow is called bioluminescence. Each species blinks in a different rhythm, like a secret code, so males and females can find each other.", x: "A firefly's light barely gives off any heat: almost all of the energy becomes light! An old-fashioned light bulb, the kind with a little wire inside, wasted most of its energy as heat.", s: ["There are more than 2,000 species of fireflies around the world.", "Baby fireflies, the larvae, glow too and eat slugs and snails.", "Bright city lights make it harder for fireflies to find each other in the dark."], ex: { t: "Light that changes with temperature", m: "two identical glow sticks, a cup of hot tap water and a cup of ice water, a grown-up", p: ["With a grown-up, activate both glow sticks by bending them until you hear a “crack.”", "Put one in the cup of hot water and the other in the cup of ice water.", "After a minute, turn off the light and compare: the one in the hot water glows brighter! The light comes from a chemical reaction, like in fireflies, and heat makes the reaction faster."] }, at: "Card 9: the firefly", m: "cards, black paper, yellow and green colored pencils or chalk", p: ["On a black card, draw fireflies blinking in the grass.", "Invent your firefly's blinking code, like blink-blink-pause.", "Write: “Cold light, made by the body!”"], q: "What can we do so fireflies keep glowing near cities?" },
es: { h: "En el campo, cuando oscureció, el pasto empezó a titilar con lucecitas verdes, como estrellitas volando. “¡Luciérnagas!”, susurró Nina, encantada. Leo quiso saber si las luces calentaban, como una lamparita. “Eso es lo más increíble”, dijo el abuelo. “¡Es una luz fría!”", t: "Las luciérnagas", f: "Las luciérnagas, también llamadas bichitos de luz, son escarabajos que hacen luz con su propio cuerpo. En la panza mezclan sustancias químicas que, juntas, brillan. Ese brillo se llama bioluminiscencia. Cada especie titila con un ritmo distinto, como un código secreto, para que los machos y las hembras se encuentren.", x: "¡La luz de la luciérnaga casi no calienta: prácticamente toda la energía se convierte en luz! Una lamparita antigua, de las que tenían un filamento, desperdiciaba la mayor parte de la energía en calor.", s: ["Hay más de 2.000 especies de luciérnagas en el mundo.", "Las crías de luciérnaga, las larvas, también brillan y comen babosas y caracoles.", "Las luces fuertes de las ciudades les complican a las luciérnagas encontrarse en la oscuridad."], ex: { t: "Luz que cambia con la temperatura", m: "dos pulseras luminosas iguales, un vaso con agua caliente de la canilla y uno con agua helada, un adulto", p: ["Con un adulto, activa las dos pulseras luminosas doblándolas hasta oír el “crac”.", "Pon una en el vaso de agua caliente y la otra en el vaso de agua helada.", "Después de un minuto, apaga la luz y compara: ¡la del agua caliente brilla más fuerte! La luz viene de una reacción química, como en la luciérnaga, y el calor hace más rápida la reacción."] }, at: "Tarjeta 9: la luciérnaga", m: "tarjetas, papel negro, lápices o tizas amarillas y verdes", p: ["En una tarjeta negra, dibuja luciérnagas titilando en el pasto.", "Inventa el código de titileo de tu luciérnaga, como titila-titila-pausa.", "Escribe: “¡Luz fría, hecha por el cuerpo!”."], q: "¿Qué podemos hacer para que las luciérnagas sigan brillando cerca de las ciudades?" } },

{ e: "🦗", art: { b: "🦗", s: ["🎻", "🌙", "🌡️", "👂"], c: ["#2A4A1B", "#7AA03A"] },
pt: { h: "Na hora de dormir, um cri-cri-cri não parava do lado de fora da janela. “Quem está cantando?”, perguntou Leo, sonolento. “Um grilo”, disse o vovô. “Mas ele não canta com a boca. Ele toca violino com as asas! E escuta com os joelhos.”", t: "Grilos e gafanhotos", f: "Os grilos machos fazem o cri-cri esfregando uma asa na outra: uma tem uma fileira de dentinhos, como um pente, e a outra tem uma borda dura que raspa nesses dentinhos. Cada espécie tem seu próprio som, e é assim que as fêmeas encontram os machos. Os gafanhotos, parentes dos grilos, são campeões de salto, com pernas de trás bem fortes.", x: "Os ouvidos do grilo ficam nas patas da frente, logo abaixo do “joelho”! E os grilos cantam mais rápido quando faz calor e mais devagar quando faz frio.", s: ["Um gafanhoto pode pular uma distância de umas 20 vezes o tamanho do próprio corpo.", "Os grilos costumam cantar à noite, e os gafanhotos, de dia.", "Algumas espécies de gafanhotos se juntam em nuvens gigantes com milhões de insetos."], ex: { t: "Violino de grilo", m: "um pente de plástico, um cartão de papel duro ou uma tampinha, um copo de plástico (opcional)", p: ["Passe a borda do cartão pelos dentes do pente, devagar e depois rápido. Escute o som!", "Encoste o pente na boca de um copo de plástico e repita: o copo deixa o som mais alto.", "É assim que o grilo faz o cri-cri: raspando uma asa com borda dura na outra, que tem dentinhos."] }, at: "Cartão 10: o grilo", m: "cartões, lápis de cor", p: ["Desenhe um grilo cantando à noite, com notinhas musicais saindo das asas.", "Desenhe uma setinha mostrando onde fica o ouvido dele.", "Escreva: “Toca com as asas, escuta com as patas!”."], q: "Que sons de bichos você escuta à noite onde você mora?" },
en: { h: "At bedtime, a chirp-chirp-chirp kept going outside the window. “Who's singing?” Leo asked sleepily. “A cricket,” said Grandpa. “But it doesn't sing with its mouth. It plays the violin with its wings! And it listens with its knees.”", t: "Crickets and grasshoppers", f: "Male crickets chirp by rubbing one wing against the other: one has a row of tiny teeth, like a comb, and the other has a hard edge that scrapes across them. Each species has its own sound, which is how females find males. Grasshoppers, cricket relatives, are jumping champions with very strong back legs.", x: "A cricket's ears are on its front legs, just below the “knee”! And crickets chirp faster when it's warm and slower when it's cold.", s: ["A grasshopper can jump about 20 times its own body length.", "Crickets usually sing at night, and grasshoppers during the day.", "Some species of locusts gather in giant swarms with millions of insects."], ex: { t: "Cricket violin", m: "a plastic comb, a stiff paper card or a bottle cap, a plastic cup (optional)", p: ["Run the edge of the card along the teeth of the comb, slowly and then quickly. Listen to the sound!", "Hold the comb against the rim of a plastic cup and do it again: the cup makes the sound louder.", "That's how a cricket chirps: scraping a hard-edged wing against another wing with tiny teeth."] }, at: "Card 10: the cricket", m: "cards, colored pencils", p: ["Draw a cricket singing at night, with musical notes coming out of its wings.", "Draw a little arrow showing where its ear is.", "Write: “Plays with its wings, hears with its legs!”"], q: "What animal sounds do you hear at night where you live?" },
es: { h: "A la hora de dormir, un cri-cri-cri no paraba del otro lado de la ventana. “¿Quién está cantando?”, preguntó Leo, con sueño. “Un grillo”, dijo el abuelo. “Pero no canta con la boca. ¡Toca el violín con las alas! Y escucha con las rodillas.”", t: "Grillos y saltamontes", f: "Los grillos machos hacen el cri-cri frotando un ala contra la otra: una tiene una hilera de dientitos, como un peine, y la otra tiene un borde duro que raspa esos dientitos. Cada especie tiene su propio sonido, y así las hembras encuentran a los machos. Los saltamontes, parientes de los grillos, son campeones de salto, con patas traseras muy fuertes.", x: "¡Los oídos del grillo están en las patas delanteras, justo debajo de la “rodilla”! Y los grillos cantan más rápido cuando hace calor y más despacio cuando hace frío.", s: ["Un saltamontes puede saltar una distancia de unas 20 veces el largo de su cuerpo.", "Los grillos suelen cantar de noche, y los saltamontes, de día.", "Algunas especies de langostas se juntan en nubes gigantes con millones de insectos."], ex: { t: "Violín de grillo", m: "un peine de plástico, una tarjeta de cartón duro o una tapita, un vaso de plástico (opcional)", p: ["Pasa el borde de la tarjeta por los dientes del peine, despacio y después rápido. ¡Escucha el sonido!", "Apoya el peine en el borde de un vaso de plástico y repite: el vaso hace el sonido más fuerte.", "Así hace el grillo el cri-cri: raspando un ala de borde duro contra la otra, que tiene dientitos."] }, at: "Tarjeta 10: el grillo", m: "tarjetas, lápices de colores", p: ["Dibuja un grillo cantando de noche, con notitas musicales saliendo de las alas.", "Dibuja una flechita que muestre dónde está su oído.", "Escribe: “¡Toca con las alas, escucha con las patas!”."], q: "¿Qué sonidos de bichos escuchas de noche donde vives?" } },
];
